type definitionVersionStatThenLoader[Q orm.Loadable] struct {
	DefinitionVersion func(...bob.Mod[*dialect.SelectQuery]) orm.Loader[Q]
	Stat              func(...bob.Mod[*dialect.SelectQuery]) orm.Loader[Q]
}

func buildDefinitionVersionStatThenLoader[Q orm.Loadable]() definitionVersionStatThenLoader[Q] {
	type DefinitionVersionLoadInterface interface {
		LoadDefinitionVersion(context.Context, bob.Executor, ...bob.Mod[*dialect.SelectQuery]) error
	}
	type StatLoadInterface interface {
		LoadStat(context.Context, bob.Executor, ...bob.Mod[*dialect.SelectQuery]) error
	}

	return definitionVersionStatThenLoader[Q]{
		DefinitionVersion: thenLoadBuilder[Q](
			"DefinitionVersion",
			func(ctx context.Context, exec bob.Executor, retrieved DefinitionVersionLoadInterface, mods ...bob.Mod[*dialect.SelectQuery]) error {
				return retrieved.LoadDefinitionVersion(ctx, exec, mods...)
			},
		),
		Stat: thenLoadBuilder[Q](
			"Stat",
			func(ctx context.Context, exec bob.Executor, retrieved StatLoadInterface, mods ...bob.Mod[*dialect.SelectQuery]) error {
				return retrieved.LoadStat(ctx, exec, mods...)
			},
		),
	}
}

// LoadDefinitionVersion loads the definitionVersionStat's DefinitionVersion into the .R struct
func (o *DefinitionVersionStat) LoadDefinitionVersion(ctx context.Context, exec bob.Executor, mods ...bob.Mod[*dialect.SelectQuery]) error {
	if o == nil {
		return nil
	}

	// Reset the relationship
	o.R.DefinitionVersion = nil
	o.R.Loaded.DefinitionVersion = false

	related, err := o.DefinitionVersion(mods...).One(ctx, exec)
	if err != nil {
		return err
	}

	o.R.DefinitionVersion = related
	o.R.Loaded.DefinitionVersion = true
	return nil
}

// LoadDefinitionVersion loads the definitionVersionStat's DefinitionVersion into the .R struct
func (os DefinitionVersionStatSlice) LoadDefinitionVersion(ctx context.Context, exec bob.Executor, mods ...bob.Mod[*dialect.SelectQuery]) error {
	if len(os) == 0 {
		return nil
	}

	definitionVersions, err := os.DefinitionVersion(mods...).All(ctx, exec)
	if err != nil {
		return err
	}

	for _, o := range os {
		if o == nil {
			continue
		}

		o.R.DefinitionVersion = nil
		o.R.Loaded.DefinitionVersion = true
	}
	// O(N+M) stitch via a map keyed by the join column (key -> []parent; was O(N*M)).
	definitionVersionStatByKey := make(map[int64][]*DefinitionVersionStat, len(os))
	for _, o := range os {
		if o == nil {
			continue
		}

		definitionVersionStatByKey[o.DefinitionVersionID] = append(definitionVersionStatByKey[o.DefinitionVersionID], o)
	}

	for _, rel := range definitionVersions {

		owners, ok := definitionVersionStatByKey[rel.ID]
		if !ok {
			continue
		}

		for _, o := range owners {

			// to-one: keep only the first matching child (matches the previous break)
			if o.R.DefinitionVersion != nil {
				continue
			}

			o.R.DefinitionVersion = rel

		}
	}

	return nil
}

// LoadStat loads the definitionVersionStat's Stat into the .R struct
